// Self-made phone-lock click: a deterministic synth (no API, no cost, no licence needed).
//
// usage: yarn sfx:click <slug> [--name click] [--force]
//
// Synthesises a 0.35 s stereo 16-bit 44.1 kHz WAV (short filtered noise tick + damped 2.4 kHz body +
// a little 180 Hz weight) into a temp file, encodes it with Remotion's bundled ffmpeg
// (libmp3lame, 128k) to src/videos/<slug>/audio/sfx/<name>.mp3. Same samples every run. Refuses to
// overwrite an existing file unless --force. Not logged in audio-log.md (nothing generated by a service).
import {spawnSync} from 'node:child_process';
import {existsSync, mkdirSync, mkdtempSync, rmSync, writeFileSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';

const usage = 'yarn sfx:click <slug> [--name click] [--force]';
const fail = (msg) => {
  console.error(`${msg}\nusage: ${usage}`);
  process.exit(1);
};
const argv = process.argv.slice(2);
if (argv.includes('--help') || argv.includes('-h')) {
  console.log(`${usage}\n\n  Writes src/videos/<slug>/audio/sfx/<name>.mp3 (default name: click). --force overwrites.`);
  process.exit(0);
}
const force = argv.includes('--force');
let name = 'click';
const pos = [];
for (let i = 0; i < argv.length; i++) {
  if (argv[i] === '--name') name = argv[++i] ?? '';
  else if (argv[i] !== '--force') pos.push(argv[i]);
}
const slug = pos[0];
if (!slug || pos.length > 1) fail('expected exactly one <slug>');
if (!/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(slug) || !/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(name)) fail('invalid slug or name');

const outFile = join('src', 'videos', slug, 'audio', 'sfx', `${name}.mp3`);
if (!existsSync(join('src', 'videos', slug))) fail(`src/videos/${slug}/ does not exist`);
if (existsSync(outFile) && !force) fail(`${outFile} exists; pass --force to overwrite`);

// Synthesis (kept identical to the original scratch version).
const sr = 44100, n = Math.round(sr * 0.35), out = new Int16Array(n * 2);
let seed = 12345; const rnd = () => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff) * 2 - 1;
let lp = 0, prev = 0;
for (let i = 0; i < n; i++) {
  const t = i / sr;
  const tick = t < 0.004 ? rnd() * Math.exp(-t / 0.0012) : 0;          // sharp transient
  const body = Math.sin(2 * Math.PI * 2400 * t) * Math.exp(-t / 0.008); // short tonal body
  const low = Math.sin(2 * Math.PI * 180 * t) * Math.exp(-t / 0.012) * 0.5; // a little weight
  let s = tick * 0.9 + body * 0.6 + low;
  lp += 0.6 * (s - lp); const hp = lp - prev * 0.0; prev = lp;          // gentle smoothing
  const v = Math.max(-1, Math.min(1, hp * 0.5));                         // ≈ -6 dBFS peak
  out[2 * i] = out[2 * i + 1] = Math.round(v * 32767);
}
const data = Buffer.from(out.buffer), h = Buffer.alloc(44);
h.write('RIFF', 0); h.writeUInt32LE(36 + data.length, 4); h.write('WAVEfmt ', 8);
h.writeUInt32LE(16, 16); h.writeUInt16LE(1, 20); h.writeUInt16LE(2, 22); h.writeUInt32LE(sr, 24);
h.writeUInt32LE(sr * 4, 28); h.writeUInt16LE(4, 32); h.writeUInt16LE(16, 34); h.write('data', 36); h.writeUInt32LE(data.length, 40);

const tmp = mkdtempSync(join(tmpdir(), 'sfx-click-'));
try {
  const wav = join(tmp, 'click.wav');
  writeFileSync(wav, Buffer.concat([h, data]));
  mkdirSync(join('src', 'videos', slug, 'audio', 'sfx'), {recursive: true});
  const r = spawnSync('npx', ['remotion', 'ffmpeg', '-hide_banner', '-nostdin', '-y', '-i', wav, '-c:a', 'libmp3lame', '-b:a', '128k', outFile], {encoding: 'utf8'});
  if (r.status !== 0) fail(`ffmpeg failed:\n${(r.stderr || '').slice(-1500)}`);
  console.log(`wrote ${outFile}`);
} finally {
  rmSync(tmp, {recursive: true, force: true});
}
